  // ── /about — opening (origin + Star Wars crawl) ──
  'about.origin.title': 'Pochodzenie',
  'about.origin.sub': 'Przesuń i czytaj',
  'about.origin.skip': 'albo pomiń',
  'about.crawl.intro': 'Dziesięć lat temu, w schronisku w sercu Europy….',
  'about.crawl.episode': 'Epizod I',
  'about.crawl.faith': 'Nowa wiara',
  'about.crawl.p1':
    'W 2016 roku do schroniska trafiło osiem czarnych szczeniąt, porzuconych w jednym pudle. Siedem znalazło dom. Tego największego nikt nie chciał — czekał cały rok. Nazywał się Hekthor.',
  'about.crawl.p2':
    'Pewnego dnia para przyszła do schroniska zobaczyć Sindy, małą białą sukę, którą chcieli adoptować. Czystym przypadkiem Hekthor był wtedy w jej kojcu — jego własny był właśnie sprzątany. Mężczyzna, który przyjechał tylko dla towarzystwa i nigdy nie chciał psa, zakochał się w czarnym psie, którego widział po raz pierwszy w życiu.',
  'about.crawl.p3':
    'Tydzień później byli już razem i zaczęła się piękna historia. Całe życie mężczyzny się zmieniło, a z czasem zrozumiał jedno: naprawdę pomóc psom w potrzebie może tylko ten, kto ma psa i wie, jak czuje się psia miłość.',
  'about.crawl.p4':
    'I tak narodził się Heroglyph — symbol, który ma zjednoczyć miłośników psów na całym świecie w największą społeczność, jaką świat kiedykolwiek znał. Społeczność, która stanie za nami, za naszymi psami i za pokoleniami, które przyjdą — za ludźmi, którzy nie boją się przyznać, że pies to nie tylko zwierzę, ale istota, która czyni nas lepszymi ludźmi.',
  'about.crawl.p5':
    'Właśnie teraz zaczyna się droga do pierwszego kamienia milowego — stworzyć 1 000 000 Heroglyphów. A ty możesz być przy tym. Bo świat zmieniają tylko ci, którzy są na tyle szaleni, by wierzyć, że potrafią.',
  'about.crawl.p6': 'Wierzymy w psa.',

  // ── /about — timeline (5 míľnikov) ──
  'about.timeline.heading': 'Historia Dogypt',
  'about.milestone.1.year': '2017',
  'about.milestone.1.tag': 'Schronisko',
  'about.milestone.1.title': 'Skarb w schronisku',
  'about.milestone.1.body':
    'Za płotem schroniska czekał czarny pies, którego nikt nie chciał. Dostał imię Hekthor. Adoptowanie go nie było ratunkiem — było początkiem wszystkiego.',
  'about.milestone.2.year': '2018',
  'about.milestone.2.tag': 'Więź',
  'about.milestone.2.title': 'Więź na zawsze',
  'about.milestone.2.body':
    'Przeprowadził mnie przez najtrudniejszy odcinek mojego życia bez jednego słowa. Każdy miłośnik psów to zna — podtrzymują cię dokładnie wtedy, gdy upadasz.',
  'about.milestone.3.year': '2019',
  'about.milestone.3.tag': 'Wędrówka',
  'about.milestone.3.title': 'Wędrówka, z której powstała książka',
  'about.milestone.3.body':
    'Razem przeszliśmy całą Słowację — 42 dni, 800 kilometrów, jedna cicha obietnica. Z tej drogi powstała książka: „Cesta s Hrdinom" — Wędrówka z Bohaterem.',
  'about.milestone.4.year': '2022',
  'about.milestone.4.tag': 'Nazwa',
  'about.milestone.4.title': 'Naród miłośników psów',
  'about.milestone.4.body':
    'Piramidy, mistyka, wieczna chwała Egiptu — ludzkość fascynuje to od tysiącleci. Połącz to z nieskończoną miłością psa, a powstanie DOGYPT. Pomysł osobiście przypieczętowałem na Expo Dubai 2022, ubrany jak faraon.',
  'about.milestone.5.year': 'Teraz',
  'about.milestone.5.tag': 'Dogypt',
  'about.milestone.5.title': 'Wędrówka zaczyna się od ciebie',
  'about.milestone.5.body':
    'DOGYPT to ruch dla każdego, kogo życie zmienił pies. Zbudowany na najstarszej i najszczerszej więzi na Ziemi. Hekthor jest założycielem #1. Ty jesteś następny.',

  // ── /about — outro + reel ──
  'about.outro.quoteLead': 'To nigdy nie był',
  'about.outro.quoteTail': '„tylko pies."',
  'about.outro.body':
    'Już znasz to uczucie — że pies to nie coś, co posiadasz, ale <strong>ktoś, kogo kochasz</strong>. A teraz wyobraź sobie tę miłość zorganizowaną, połączoną, <strong>na tyle potężną, by zmieniać rzeczy.</strong> I właśnie dlatego istnieje <strong>DOGYPT</strong>.',
  'about.outro.name1': 'Matej',
  'about.outro.and': 'i',
  'about.outro.name2': 'Hekthor',
  'about.outro.cta': 'Zostań Dogiptianinem',
  'about.reel.prev': 'Poprzednie zdjęcie',
  'about.reel.next': 'Następne zdjęcie',

