  "payment.transparency.title": "100% Przejrzystości",
  "payment.transparency.hint": "Dotknij kategorii, aby zobaczyć szczegóły.",
  "payment.transparency.eyebrow": "Gdzie trafiają pieniądze?",
  "transparency.part.development": "Rozwój",
  "transparency.part.affiliate": "Społeczność",
  "transparency.part.directHelp": "Ratunek",
  "transparency.part.hekthorBowl": "Miska Hekthora",
  "transparency.part.development.note": "Budowa narodu i finansowanie wszystkiego, co go napędza — ludzi, którzy pchają DOGYPT naprzód, oraz usług, narzędzi i serwerów za nimi. To silnik ruchu, a każdy wydatek będzie udokumentowany i jawnie opublikowany.",
  "transparency.part.affiliate.note": "Nie reklamy — ludzie. To trafia prosto na konta Dogiptian, którzy szerzą wiarę, wypłacane w BONES: mogą je później wydać w DOGYPT albo przekazać psom w potrzebie. Inwestujemy w sforę, nigdy w drogi marketing — sfora niesie słowo o wiele dalej.",
  "transparency.part.directHelp.note": "Prosto do psów w potrzebie — schroniska, karma, rachunki u weterynarza i akcje ratunkowe. Bez pośredników, bez kosztów ogólnych: ta część trafia tam, gdzie jest cierpienie, a każdy grosz jest udokumentowany, poparty rachunkiem i jawny dla całej sfory.",
  "transparency.part.hekthorBowl.note": "Pies-założyciel, od którego wszystko się zaczęło. Ta część to przejrzysta nagroda dla Hekthora i jego pana — po prostu ich wypłata. Ich celem jest zostać milionerem — milion psów w sforze. Bez Hekthora DOGYPT w ogóle by nie powstał — ta miska to podziękowanie.",
  "legal.eyebrow": "DOGYPT · Legal",
  "legal.motto": "DOGYPT · Wierzymy w psa",
  "about.council.formTitle": "Dołącz do misji",
  "about.council.consent": "Przesyłając formularz, zgadzam się na otrzymywanie wiadomości e-mail od DOGYPT — zero reklam, tylko mobilizacja watahy i komunikacja.",
  "about.footer.motto": "Wierzymy w psa.",

