  'heroglyph.sales.transparency.footer': 'Każde euro pozostaje jawne, na oczach każdego członka. Nie płacisz firmie — karmisz sforę.',
  'entry.declare.eyebrow': 'Niniejszym oświadczam',
  'entry.title': 'In Dog I Trust',
  'entry.subtitle': 'To nie żart. Każda poważna religia musi zadeklarować te rzeczy.',
  'entry.criteria.theology.title': 'Teologia',
  'entry.criteria.theology.body': 'Najlepszy przyjaciel, strażnik, nauczyciel, towarzysz każdej przygody. Pies daje miłość bez warunków — a idąc u jego boku, stajemy się bardziej ludzcy.',
  'entry.criteria.canon.title': 'Kanon',
  'entry.criteria.canon.body': 'Każda wiara ma swoje pismo. Naszym jest DOGMA: nasza więź z psem spisana w dwunastu rozdziałach, do przeczytania za darmo na dogma.dogypt.com.',
  'entry.criteria.community.title': 'Wspólnota',
  'entry.criteria.community.body': 'Jesteśmy miłośnikami psów z celem. Każdy z nas w pojedynkę może zmienić niewiele — razem nasza siła nie ma granic.',
  'entry.criteria.symbol.title': 'Symbol',
  'entry.criteria.symbol.body': 'Każda wiara ma swój znak. Naszym jest Heroglyph: unikalny święty symbol dla każdego psa, zrozumiały w każdym języku, wszędzie.',
  'entry.criteria.ritual.title': 'Rytuał',
  'entry.criteria.ritual.body': 'Spacer. Codzienna terapia, która utrzymuje ciało i umysł w formie — a także duszę. Najstarszy rytuał, który już pielęgnujemy, choć nikt nam nie każe.',
  'entry.criteria.vision.title': 'Wizja',
  'entry.criteria.vision.body': 'Wznieść więź między człowiekiem a psem — i walczyć o szacunek oraz lepsze życie, które należy się każdemu psu.',
  'entry.criteria.offerings.title': 'Ofiara',
  'entry.criteria.offerings.note': '(symboliczny dar)',
  'entry.criteria.offerings.pill': '€11 · jednorazowo',
  'entry.criteria.offerings.tag': '100% przejrzystości',
  'entry.criteria.offerings.body': '€11, jeden raz. Symboliczna ofiara — każdy przychód i każdy wydatek w księdze otwartej dla wszystkich. Energia, która utrzymuje nas przy życiu.',
  'entry.criteria.legitimacy.title': 'Prawomocność',
  'entry.criteria.legitimacy.pill': 'brakuje {count} członków',
  'entry.criteria.legitimacy.body': 'Tysiąc założycieli i będziemy dość silni, by zarejestrować się jako naród, który prawo musi uznać. Ostatni próg — tylko ty możesz go osiągnąć.',
