  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. W sforze: co widzą inni Członkowie",
  "privacy.s12.body": "Artykuł 3 opisuje publiczny GodsGrid. W sforze — w strefie dla Członków — inni zalogowani Członkowie widzą więcej: twoje imię, twój dogiptański numer porządkowy, imię i zdjęcie twojego psa, atrybuty, które wypełniłeś o psie, wycieczki, które zapisałeś lub ogłosiłeś, twoje oceny i komentarze oraz wszystko, co napisałeś na swoim profilu. Nie widzą twojego adresu e-mail, adresu pocztowego, danych płatności ani twoich wiadomości z kimkolwiek innym. Gdy ogłosisz wycieczkę jako otwartą, trasa, data i twój pies staną się widoczne dla każdego Członka, aby mógł poprosić o przyłączenie — to właśnie znaczy ogłoszenie. Wycieczkę, którą zostawisz prywatną, widzisz tylko ty i ludzie, którzy już idą. Którą z tych dwóch opcji wybierzesz, zależy od ciebie i możesz to zmienić w każdej chwili.",
  "privacy.s13.title": "13. Wiadomości i zgłoszenia",
  "privacy.s13.body": "Prywatne wiadomości między Członkami przechowujemy w naszej bazie danych (Supabase), aby konwersacje przetrwały między sesjami. Podstawa prawna: art. 6 ust. 1 lit. b) RODO — są częścią członkostwa, które opłaciłeś. Nie czytamy ich rutynowo i nigdy nie używamy ich do reklamy ani profilowania. Konwersację otwieramy tylko wtedy, gdy zostanie zgłoszona, gdy badamy konkretne naruszenie lub incydent bezpieczeństwa, albo gdy wymaga tego prawo. Zgłoszenie zapisuje wybrany przez ciebie powód, twoją opcjonalną notatkę i odniesienie do tego, co zgłosiłeś — nie osobną kopię. Blokowanie zapisuje się jako para identyfikatorów członków. Jeśli usuniesz swoje konto, twoje wiadomości odejdą z nim; kopia w wątku drugiej osoby zostaje, oznaczona jako od usuniętego członka, bo ta konwersacja jest też jej.",
  "terms.s12.title": "12. Treści, które publikujesz",
  "terms.s12.body": "Oprócz swojego HEROGLYPHu możesz publikować w sforze treści: zdjęcia z wycieczek, trasy i miejsca, opisy wycieczek, oceny, komentarze i pytania oraz wszystko, co napiszesz na swoim profilu. Gdy oznaczysz wycieczkę jako przebytą, inni Członkowie zobaczą twoje imię i psy, które przeszły ją z tobą. Zachowujesz prawo własności do wszystkiego, co opublikujesz. Publikując to, udzielasz spółce DOGYPT s.r.o. ogólnoświatowej, bezpłatnej, niewyłącznej licencji na przechowywanie, wyświetlanie i adaptację tej treści w celu prowadzenia i promowania Usługi — na przykład pokazania twojego zdjęcia z wycieczki na mapie, w liście wycieczek lub na karcie do udostępnienia. Licencja trwa, dopóki treść jest w Usłudze; usunięcie treści lub konta ją kończy, z wyjątkiem kopii zapasowych, które wygasają w swoim normalnym cyklu. Nie sprzedajemy twojej treści i nie licencjonujemy jej nikomu innemu do własnego użytku. Publikuj tylko to, do czego masz prawo — w tym zdjęcia zrobione przez kogoś innego i osoby, które są na nich rozpoznawalne.",
  "terms.s13.title": "13. Wiadomości między Członkami",
  "terms.s13.body": "Członkowie mogą pisać do siebie bezpośrednio. Wiadomości są prywatne między uczestnikami — nie czytamy ich rutynowo i nigdy nie używamy ich do reklamy. Przechowujemy je na naszych serwerach, aby konwersacja wciąż tam była, gdy wrócisz, i możemy przeczytać konwersację w trzech przypadkach: gdy ktoś ją zgłosi, gdy badamy konkretne naruszenie lub incydent bezpieczeństwa, albo gdy wymaga tego prawo. Innego Członka możesz zablokować w każdej chwili; blokowanie jest natychmiastowe i działa w obie strony. Traktuj wiadomości jak każdą inną rozmowę online — nie wysyłaj danych płatności, haseł ani dokumentów, których nie chcesz mieć przechowywanych.",
  "terms.s14.title": "14. Zgłaszanie i moderacja",
  "terms.s14.body": "Profile, wycieczki i konwersacje można zgłosić. Zgłoszenie trafia do nas i czyta je człowiek — dziś jest to założyciel, Matej Stacho. Naszym celem jest przyjrzeć się każdemu zgłoszeniu w ciągu 7 dni. Zależnie od tego, co znajdziemy, możemy nie zrobić nic, usunąć treść, ostrzec Członka, ograniczyć to, co może publikować, albo zamknąć jego konto. Jeśli podejmiemy działanie wobec twojej treści, poinformujemy cię o powodzie e-mailem, a ty możesz odpowiedzieć i się odwołać. Możemy też usunąć treść z własnej inicjatywy, gdy łamie Artykuł 7. Świadome lub powtarzane naruszenia — nękanie, spam, fałszywe wycieczki, treści dotyczące osób niepełnoletnich — kończą konto bez dalszego ostrzeżenia.",
