  "pack.cal.life.tip.weight.body": "Ze wszystkiego, co można zrobić dla psa, jedna rzecz ma najtwardszy dowód wpływu na długość życia: nie dopuścić, by przybrał na wadze. Różnica między szczupłym a lekko otyłym psem to lata, nie miesiące. Żebra powinny być wyczuwalne bez naciskania.",
  "pack.cal.life.tip.move.title": "Ruch w prawdziwym terenie, nie kółko wokół bloku",
  "pack.cal.life.tip.move.body": "Nierówny teren utrzymuje w ruchu stawy, mięśnie i głowę. Każda wycieczka, którą zapiszesz, zmienia się na tej siatce w ciemny tydzień — a ciemne tygodnie to jedyne, na co naprawdę masz wpływ.",
  "pack.cal.life.tip.food.title": "Jedzenie, które pies rozpoznaje jako jedzenie",
  "pack.cal.life.tip.food.body": "Im mniej kroków między surowym składnikiem a miską, tym mniej może pójść źle po drodze. Granulat to nie grzech, ale też nie dieta — to skrót.",
  "pack.cal.life.tip.chem.title": "Chemia tylko wtedy, gdy jest naprawdę potrzebna",
  "pack.cal.life.tip.chem.body": "Całoroczne środki przeciwpasożytnicze, narkoza dla wygody i antybiotyki „na wszelki wypadek” to decyzje, nie rutyna. Pytaj przy każdej z nich: co się stanie, jeśli to odpuszczę? Gdzie odpowiedź brzmi „nic”, odpuść.",
  "pack.cal.life.tip.stress.title": "Spokój liczy się tak samo jak ruch",
  "pack.cal.life.tip.stress.body": "Pies, który jest zawsze w gotowości, spala ciało od wewnątrz. Nieprzerwany sen, przewidywalny dzień i cisza po wysiłku to nie lenistwo — to godziny, w których ciało się naprawia.",
  "pack.cal.life.tip.protocol.title": "Protokół zamiast panicznego biegu do weterynarza",
  "pack.cal.life.tip.protocol.body": "Odrobaczanie, koprologia i badania krwi mają w kalendarzu swoje okna. Pies, któremu dwa razy w roku sprawdzasz krew, nie jest leczony — jest wyprzedzany.",
  "pack.cal.life.tip.joints.title": "Stawy rozwiązuje się ZANIM zaczną boleć",
  "pack.cal.life.tip.joints.body": "Twój pies jest teraz w paśmie seniora. Kuracja stawowa ma w kalendarzu okno od listopada — nie dlatego, że kuleje, ale żeby nigdy nie musiał.",
