  "pack.hero.popStatusEyebrow": "Status",
  "pack.hero.popPawtner1": "Pawtner to twoja pozycja w sforze — jesteś towarzyszem psa, dla którego stworzyłeś HEROGLYPH. Bez heroglyphu nie jesteś Dogiptianinem.",
  "pack.hero.rolePack": "Sfora",
