  "pack.msg.modMenuExplain": "Blokowanie jest natychmiastowe i działa w obie strony — żadne z was nie napisze już do drugiego. Zgłoszenie nikogo nie karze: rozmowę w ciszy przeczyta opiekun sfory i odezwie się tylko wtedy, gdy będzie coś do rozwiązania.",
