  "pack.msg.inboxEmpty": "Jeszcze żadnych wiadomości. Możesz napisać do każdego z DOGYPT — ze SNIFFERa, z jego profilu albo z wycieczki, na którą idzie.",
  "pack.msg.inboxEmptyNoSniffer": "Jeszcze żadnych wiadomości. Możesz napisać do każdego z DOGYPT — z jego profilu albo z wycieczki, na którą idzie.",
  "pack.msg.openSniffer": "Otwórz SNIFFER",
