  "pack.nature.bal.metal.deficiency.pneumonia": "Zapalenie płuc",
  "pack.nature.bal.water.excess.loose-stool": "Rozwolniony stolec",
  "pack.nature.bal.water.excess.lethargy": "Apatia",
  "pack.nature.bal.water.excess.headaches": "Bóle głowy",
  "pack.nature.bal.water.excess.headaches.note": "Wrażliwy na dotyk głowy albo wciska czoło w ścianę",
  "pack.nature.bal.water.excess.stones": "Kamienie w nerkach albo pęcherzu",
  "pack.nature.bal.water.excess.arthritis": "Artretyzm",
  "pack.nature.bal.water.excess.tumors": "Nowotwory mózgu, kręgosłupa albo podbrzusza",
