  "pack.nature.bal.wood.excess.reflux": "Beknięcia, przełykanie na sucho, oblizywanie pysków",
  "pack.nature.bal.wood.excess.irritability": "Krótki lont — wybucha prawie bez ostrzeżenia",
  "pack.nature.bal.wood.excess.hyperactivity": "Nadpobudliwość",
  "pack.nature.bal.wood.excess.digestive-upset": "Rozdrażnione trawienie",
