  "pack.nature.intro.body": "Dwadzieścia dwa pytania i jedna lista. Dowiesz się, z czego jest zrobiony twój pies, jaką pracę wykonuje dla rodziny i w którą stronę przechyla się właśnie jego równowaga.",
