  "pack.nature.ans.sometimes": "Czasem",
  "pack.nature.ans.no": "Nie",
  "pack.network.ads.body": "Płatna reklama to bardzo nieefektywny sposób, żeby znaleźć nowych miłośników psów — i sposób wyrzucania naszych pieniędzy wielkim korporacjom. Dużo lepiej działa nagradzanie wprost członków ruchu za aktywność. Jest jeden haczyk: <strong style=\"font-weight:600\">naprawdę zadziała to tylko, jeśli wyjdziesz i powiesz o nas ludziom wokół ciebie</strong> :)",
  "pack.network.ads.header": "Czemu w ten sposób?",
