  "pack.network.capped.none": "Z tego przelewu żadnego oddania — twoje dary już zrównują wszystko, co przeżyłeś. BONES i tak przejdą. <i>Pieniądze podwajają lata, nigdy ich nie zastąpią.</i>",
  "pack.network.capped.room": "Limit na <b style=\"color:#2a1608\">{room}</b> — dar może zrównać tylko to, co już przeżyłeś ({lived} oddania do tej pory). BONES i tak przejdą; honor czeka na dni.",
