  "pack.network.inLine": "W twojej linii",
  "pack.network.info.bones.body": "BONES to wewnętrzna waluta DOGYPT — żartobliwa nazwa dla prawdziwej rzeczy. Pies płaci kośćmi; my też. <b>Zarabiasz</b> je, przyprowadzając miłośników psów do sfory i poruszając ruch do przodu, a <b>wydajesz</b> je wewnątrz DOGYPT: wspierając zbiórki dla schronisk, odbierając merch, a później płacąc innym Dogiptianom za to, co tworzą. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "Co to są BONES?",
  "pack.network.info.why.body": "Ruch tej wielkości nie można kupić — żaden budżet nie dosięgnie nieznajomego tak, jak jeden Dogiptianin dosięga przyjaciela. Więc sfora stawia nagrodę tam, gdzie jest zasięg — u ciebie. Gdy ktoś przyłączy się przez twój link, dostajesz <b>{l1} BONES</b>; gdy przyprowadzi kolejnego, dostajesz jeszcze <b>{l2}</b>. Każdy Dogiptianin, który szerzy słowo, nie jest sprzedawcą — jest misjonarzem, i szanujemy tę pracę.",
  "pack.network.info.why.cap": "Czemu cię prosimy",
  "pack.network.intro": "Ruch rośnie tylko wtedy, gdy jego członkowie niosą przesłanie i przyprowadzają nowych ludzi. Więc prosimy cię wprost: <strong style=\"color:#2a1608;font-weight:600\">zaproś miłośników psów, których znasz</strong>. Oto dokładnie, jak to działa.",
