  "onepage.apps.dogid.lede": "Każdy szczegół o twoim psie w jednym miejscu — klucz do spersonalizowanej opieki od weterynarza i AINUBIS.",
  "onepage.apps.dogtrip.lede": "Wędruj po sprawdzonych trasach przyjaznych psom i zapisuj własne. Zbieraj punkty i odznaki za wasze aktywne życie razem.",
