  "onepage.hbook.0.title": "Dawno, dawno temu…",
  "onepage.hbook.0.glyph": "Heroglyph Hekthora",
  "onepage.hbook.0.sub": "Hekthor · pies #1",
  "onepage.hbook.0.cap": "Lustro",
  "onepage.hbook.1.ini": "U",
  "onepage.hbook.1.lead": "rodził się niechciany. Wyrzucony w pudle, gdzie z braćmi czekał na śmierć.",
  "onepage.hbook.1.txt": "Osiem maleńkich dusz trafiło do schroniska. Siedem z nich znalazło dom. Został tylko jeden — największy, z największym temperamentem. Po roku, zupełnym przypadkiem, spotkał Mateja, który psa nigdy nie planował. Przeskoczyła iskra i od czerwca 2017 idą przez życie razem.",
  "onepage.hbook.1.cap": "Ośmiu w pudle",
  "onepage.hbook.2.ini": "U",
  "onepage.hbook.2.lead": "ratował ludzkie życie. Pojawił się w jego najtrudniejszym okresie.",
  "onepage.hbook.2.txt": "W najciemniejszych czasach był dla Mateja oparciem — wyciągnął go ze złych myśli, z mieszkania w przyrodę. Najpierw poznawali okoliczne uliczki, potem lasy i góry. Przeszli całą Słowację (820 km) i odbyli road tripy po Europie. Połączyła ich przygoda i wolne życie w drodze.",
  "onepage.hbook.2.cap": "Z biura w świat",
  "onepage.hbook.3.ini": "J",
  "onepage.hbook.3.lead": "ego czysta dusza przyniosła wizję globalnego ruchu dla miłośników psów.",
  "onepage.hbook.3.txt": "Życie z psem to najpiękniejszy rozdział w życiu każdego człowieka. Psiarze to zupełnie inny rodzaj ludzi — wciąż rozwiązują te same specyficzne problemy i łączy ich miłość do psów. A gdyby ta historia stała się czymś pożytecznym?",
  "onepage.hbook.3.cap": "Rodzi się wizja",
  "onepage.hbook.4.ini": "D",
  "onepage.hbook.4.lead": "ziesięć najpiękniejszych lat ma za sobą, a przed sobą co najmniej kolejne dziesięć!",
  "onepage.hbook.4.txt": "Hekthor zainspirował Mateja, by nauczyć się o psach wszystkiego — psychologii, treningu, sportu, a przede wszystkim długowieczności. Cała ta wiedza posłuży wszystkim w DOGYPT: nie kolejny wymyślny portal społecznościowy, ale sieć z sensowną treścią. A wszystko to przez „zwykłego” psa ze schroniska.",
  "onepage.hbook.4.cap": "Założyciel #1",
  "onepage.hbook.5.ini": "D",
  "onepage.hbook.5.lead": "ziś mieszka na Słowacji — w lasach, w górach i nad jeziorami.",
  "onepage.hbook.5.txt": "Aportowanie z wody to jego największa miłość. Jest w świetnej formie, mądry, pokorny i najlepszy towarzysz, jakiego można sobie wymarzyć. Gdy nie ma nas na dworze, pilnuje w domu dwóch kocurów, Gary'ego i Ybyego, których uratował z ulicy.",
  "onepage.hbook.5.cap": "Stróż domu",
  "onepage.apps.sniffer.b1": "Kumpel na wycieczki i codzienne spacery",
  "onepage.apps.sniffer.b2": "Para, grupa albo road trip",
  "onepage.apps.sniffer.b3": "Swatanie psów i ich ludzi",
  "onepage.apps.sniffer.b4": "Napisz do nich prosto ze SNIFFER",
  "onepage.apps.ainubis.b1": "AI, która zna twojego psa",
